//! Selective publication: only explicitly named agent artifacts reach the site, and no
//! generated byte carries a private artifact. Context stays complete.
use entwine_core::*;
use entwine_engine::*;
use std::{fs, path::Path};

const PUBLIC_SKILL: &str = ".agents/skills/public-skill/SKILL.md";
const PUBLIC_SKILL_2: &str = ".agents/skills/second-skill/SKILL.md";
const PRIVATE_SKILL: &str = ".agents/skills/private-skill/SKILL.md";
const PRIVATE_RULES: &str = "AGENTS.md";
const CANARIES: [&str; 3] = [
    "CANARY-PRIVATE-SKILL-7f3a",
    "CANARY-PRIVATE-RULES-91bc",
    "CANARY-PRIVATE-NESTED-02de",
];

fn write(root: &Path, name: &str, text: &str) {
    let path = root.join(name);
    fs::create_dir_all(path.parent().unwrap()).unwrap();
    fs::write(path, text).unwrap();
}

fn repository() -> tempfile::TempDir {
    let temp = tempfile::tempdir().unwrap();
    let r = temp.path();
    write(r, "docs/index.md", "# Home\n\nSee the [public skill](../.agents/skills/public-skill/SKILL.md) and the [internal rules](../AGENTS.md).\n");
    write(r, "docs/guide.md", "# Guide\n\nBack to [home](index.md).\n");
    write(r, PUBLIC_SKILL, "---\nname: public-skill\ndescription: Visible skill.\n---\n# Public skill\n\nPair with [the second](../second-skill/SKILL.md), the [private one](../private-skill/SKILL.md), the [rules](../../../AGENTS.md) and the [guide](../../../docs/guide.md).\n");
    write(
        r,
        ".agents/skills/public-skill/references/notes.md",
        "# Notes\n",
    );
    write(r, PUBLIC_SKILL_2, "---\nname: second-skill\ndescription: Another visible skill.\n---\n# Second\n\nBack to [public](../public-skill/SKILL.md).\n");
    write(r, PRIVATE_SKILL, &format!("---\nname: private-skill\ndescription: {}\n---\n# Private skill\n\nSecret [public](../public-skill/SKILL.md).\n", CANARIES[0]));
    write(
        r,
        PRIVATE_RULES,
        &format!(
            "# Rules\n\n{}\n\nUse [public](.agents/skills/public-skill/SKILL.md).\n",
            CANARIES[1]
        ),
    );
    write(
        r,
        "packages/app/CLAUDE.md",
        &format!("# App\n\n{}\n", CANARIES[2]),
    );
    temp
}

fn config(selected: &[&str]) -> Config {
    Config {
        discovery: DiscoveryConfig {
            agent_instructions: true,
            skills: true,
        },
        site: SiteConfig {
            public_agent_paths: selected.iter().map(|s| s.to_string()).collect(),
            ..Default::default()
        },
    }
}

fn compile(root: &Path, config: &Config) -> Compilation {
    let c = compile_with_config(root, root, None, config).unwrap();
    assert!(!c.has_errors(), "{:?}", c.diagnostics);
    c
}

fn all_output(c: &Compilation) -> Vec<(String, String)> {
    let mut files: Vec<_> = render(c)
        .unwrap()
        .into_iter()
        .map(|f| (f.path, String::from_utf8_lossy(&f.contents).into_owned()))
        .collect();
    files.sort();
    files
}

fn private_markers() -> Vec<String> {
    let mut markers: Vec<String> = CANARIES.iter().map(|c| c.to_string()).collect();
    markers.extend([
        "private-skill".into(),
        "Private skill".into(),
        "skills/private".into(),
        "instructions/AGENTS".into(),
        "instructions/packages".into(),
        "packages/app".into(),
    ]);
    markers
}

#[test]
fn only_selected_artifacts_are_published_and_nothing_private_leaks() {
    let temp = repository();
    let c = compile(temp.path(), &config(&[PUBLIC_SKILL, PUBLIC_SKILL_2]));
    let files = all_output(&c);
    for (path, text) in &files {
        for marker in private_markers() {
            assert!(!text.contains(&marker), "{path} leaks {marker}");
            assert!(!path.contains(&marker), "{path} is a private path");
        }
    }
    let paths: Vec<_> = files.iter().map(|(p, _)| p.as_str()).collect();
    assert!(paths.contains(&"__entwine/agents/index.html"));
    assert!(paths.contains(&"__entwine/agents/skills/dot-agents/skills/public-skill/index.html"));
    assert!(paths.contains(&"__entwine/agents/skills/dot-agents/skills/second-skill/index.html"));
    assert!(!paths
        .iter()
        .any(|p| p.contains("instructions/") && !p.ends_with("agents/instructions/index.html")));
    assert!(!paths.iter().any(|p| p.contains("private-skill")));

    let agents = c.site.agents.as_ref().unwrap();
    assert_eq!(agents.entries.len(), 2);
    // The public skill still links its sibling and the documentation, but not private files.
    let public = agents
        .entries
        .iter()
        .find(|e| e.details.path == PUBLIC_SKILL)
        .unwrap();
    let references: Vec<_> = public.references.iter().map(|r| r.title.as_str()).collect();
    assert!(references.contains(&"second-skill") && references.contains(&"Guide"));
    assert_eq!(references.len(), 2);
    assert!(!public.backlinks.iter().any(|b| b.title.contains("rivate")));
    let page = files
        .iter()
        .find(|(p, _)| p == "__entwine/agents/skills/dot-agents/skills/public-skill/index.html")
        .unwrap();
    assert!(page.1.contains("second-skill") && page.1.contains("guide"));
    // Graph: no private node, edge, or reference.
    assert!(c
        .graph
        .nodes
        .iter()
        .all(|n| !n.id.0.contains("private") && !n.id.0.ends_with("CLAUDE.md")));
    assert!(c
        .graph
        .edges
        .iter()
        .all(|e| !format!("{e:?}").contains("private")));
    assert_eq!(
        c.graph
            .nodes
            .iter()
            .filter(|n| n.artifact.is_agent_facing())
            .count(),
        2
    );
    // The documentation page that linked the private rules does not link a generated route.
    let index = files.iter().find(|(p, _)| p == "index.html").unwrap();
    assert!(!index.1.contains("instructions"));
    assert!(index
        .1
        .contains("__entwine/agents/skills/dot-agents/skills/public-skill/"));
}

#[test]
fn context_and_discovery_stay_complete_when_publication_is_selective() {
    let temp = repository();
    let selective = compile(temp.path(), &config(&[PUBLIC_SKILL]));
    let everything = compile(
        temp.path(),
        &Config {
            discovery: config(&[]).discovery,
            site: SiteConfig {
                include_agent_knowledge: true,
                ..Default::default()
            },
        },
    );
    let private_only = compile(temp.path(), &config(&[]));
    let json = |c: &Compilation| context_json(&c.context).unwrap();
    // Link hrefs legitimately depend on whether a target is published; everything else
    // (documents, content, relations, backlinks, agent details) must be identical.
    let essence = |c: &Compilation| {
        let mut value: serde_json::Value = serde_json::from_str(&json(c)).unwrap();
        for document in value["documents"].as_array_mut().unwrap() {
            for link in document["links"].as_array_mut().unwrap() {
                link["href"] = serde_json::Value::Null;
            }
        }
        value
    };
    assert_eq!(essence(&selective), essence(&everything));
    assert_eq!(essence(&selective), essence(&private_only));
    assert!(json(&selective).contains(CANARIES[1]) && json(&selective).contains(CANARIES[0]));
    assert!(private_only.site.agents.is_none());
}

#[test]
fn selecting_nothing_publishes_nothing_and_generates_no_agents_routes() {
    let temp = repository();
    let c = compile(temp.path(), &config(&[]));
    assert!(c.site.agents.is_none());
    for (path, text) in all_output(&c) {
        assert!(!path.contains("agents/"), "{path}");
        for marker in private_markers() {
            assert!(!text.contains(&marker), "{path} leaks {marker}");
        }
    }
}

#[test]
fn legacy_publish_everything_keeps_working() {
    let temp = repository();
    let mut all = config(&[]);
    all.site.include_agent_knowledge = true;
    let c = compile(temp.path(), &all);
    assert_eq!(c.site.agents.as_ref().unwrap().entries.len(), 5);
    let files = all_output(&c);
    assert!(files.iter().any(|(_, t)| t.contains(CANARIES[1])));
}

#[test]
fn output_is_deterministic() {
    let temp = repository();
    let a = all_output(&compile(
        temp.path(),
        &config(&[PUBLIC_SKILL_2, PUBLIC_SKILL]),
    ));
    let b = all_output(&compile(
        temp.path(),
        &config(&[PUBLIC_SKILL, PUBLIC_SKILL_2]),
    ));
    assert_eq!(a, b);
}

#[test]
fn contradictory_unsafe_and_unknown_selections_are_rejected() {
    let temp = repository();
    let root = temp.path();
    // Symbolic links need privileges on Windows; the escape check is exercised on Unix.
    let linked = cfg!(unix);
    #[cfg(unix)]
    std::os::unix::fs::symlink(
        root.join(".agents/skills/private-skill"),
        root.join(".agents/skills/linked"),
    )
    .unwrap();
    let check = |config: &Config, expected: &str| {
        let error = compile_with_config(root, root, None, config)
            .unwrap_err()
            .to_string();
        assert!(
            error.contains(expected),
            "{error} should contain {expected}"
        );
    };
    let mut contradictory = config(&[PUBLIC_SKILL]);
    contradictory.site.include_agent_knowledge = true;
    check(&contradictory, "contradicts");
    for (bad, expected) in [
        ("/etc/AGENTS.md", "absolute"),
        ("../AGENTS.md", "normalized"),
        (".agents/../AGENTS.md", "normalized"),
        ("C:/x/AGENTS.md", "absolute"),
        (".agents\\skills\\x\\SKILL.md", "separators"),
        (".agents/skills/*/SKILL.md", "exact"),
        ("", "empty"),
        (".agents/skills/", "file"),
        ("docs/index.md", "not an agent artifact"),
        (".agents/skills/missing/SKILL.md", "not discovered"),
    ] {
        check(&config(&[bad]), expected);
    }
    if linked {
        check(
            &config(&[".agents/skills/linked/SKILL.md"]),
            "symbolic link",
        );
    }
    check(&config(&[PUBLIC_SKILL, PUBLIC_SKILL]), "more than once");
    let mut skills_off = config(&[PRIVATE_RULES]);
    skills_off.discovery.agent_instructions = false;
    check(&skills_off, "discovery switch is off");
    let mut disabled = config(&[PUBLIC_SKILL]);
    disabled.discovery = DiscoveryConfig::default();
    check(&disabled, "requires [discovery]");
}

#[test]
fn authored_markdown_is_not_rewritten() {
    let temp = repository();
    let before = fs::read_to_string(temp.path().join(PUBLIC_SKILL)).unwrap();
    compile(temp.path(), &config(&[PUBLIC_SKILL]));
    assert_eq!(
        fs::read_to_string(temp.path().join(PUBLIC_SKILL)).unwrap(),
        before
    );
}

#[test]
fn config_parses_the_new_key_strictly() {
    let parsed = parse_config(&format!(
        "[discovery]\nskills = true\n\n[site]\npublic_agent_paths = [\"{PUBLIC_SKILL}\"]\n"
    ))
    .unwrap();
    assert_eq!(
        parsed.site.public_agent_paths,
        vec![PUBLIC_SKILL.to_string()]
    );
    assert!(parse_config("[site]\npublic_agent_paths = \"x\"\n").is_err());
}
